// Clean scraped website text, normalise form fields, create a ticket ID
const body = $('Webhook: Contact Form').item.json.body || {};
const raw = $input.item.json.data ?? $input.item.json.body ?? '';
const html = typeof raw === 'string' ? raw : JSON.stringify(raw);

const cleanText = html
  .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const email = String(body.work_email || body.email || '').trim();
const message = String(body.process_takes_most_time || body.message || '').trim();
const wantsCopy = [true, 'true', 'on', 'yes', '1', 1].includes(body.email_copy);

const ticketId = 'AS-' + Date.now().toString(36).toUpperCase()
  + Math.random().toString(36).slice(2, 8).toUpperCase();

return {
  json: {
    ticket_id: ticketId,
    user_name: String(body.name || '').trim() || 'Valued Client',
    user_email: email,
    has_valid_email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email),
    user_message: message || '(no message provided)',
    wants_email_copy: wantsCopy,
    user_message_html: esc(message || '(no message provided)').replace(/\n/g, '<br>'),
    user_name_html: esc(String(body.name || '').trim() || 'Valued Client'),
    website_context: cleanText.substring(0, 20000)
  }
};

