// Parse the agent's escalation output and store the ticket
const t = $('Code: Clean Inputs & Create Ticket').item.json;
const out = String($input.item.json.output || '');

const summary = (out.match(/SUMMARY:\s*([\s\S]*?)(?=\n\s*DRAFT:|$)/i) || [])[1]?.trim()
  || 'Customer needs a human reply.';
const draft = (out.match(/DRAFT:\s*([\s\S]*)$/i) || [])[1]?.trim() || '';

const store = $getWorkflowStaticData('global');
store.tickets = store.tickets || {};

// Prune tickets older than 30 days
const now = Date.now();
for (const [id, tk] of Object.entries(store.tickets)) {
  if (now - (tk.created_at || 0) > 30 * 864e5) delete store.tickets[id];
}

store.tickets[t.ticket_id] = {
  status: 'pending',
  name: t.user_name,
  email: t.user_email,
  message: t.user_message,
  summary,
  draft,
  created_at: now
};

return {
  json: {
    ticket_id: t.ticket_id,
    user_name: t.user_name,
    user_email: t.user_email,
    has_valid_email: t.has_valid_email,
    user_message: t.user_message,
    user_message_html: t.user_message_html,
    user_name_html: t.user_name_html,
    summary,
    summary_html: summary.replace(/&/g, '&amp;').replace(/</g, '&lt;'),
    draft_html: (draft || '(none)').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/\n/g, '<br>'),
    draft
  }
};

// Turn the owner's email reply into a customer answer
const OWNER_EMAIL = 'n8ncapetown@gmail.com'.toLowerCase();   // <-- the mailbox you reply from

const store = $getWorkflowStaticData('global');
store.tickets = store.tickets || {};

function stripQuoted(t) {
  t = '\n' + String(t).replace(/\r/g, '');
  const markers = [
    /\n\s*On [\s\S]{0,300}?wrote:\s*\n/i,          // Gmail / Apple Mail
    /\n\s*-{2,}\s*Original Message/i,               // Outlook (classic)
    /\n\s*_{10,}/,                                   // Outlook (web)
    /\n\s*From:\s.+\n\s*(Sent|Date):/i,              // Outlook headers
    /\n>/                                            // quoted lines
  ];
  let cut = t.length;
  for (const m of markers) {
    const i = t.search(m);
    if (i >= 0 && i < cut) cut = i;
  }
  return t.slice(0, cut).trim();
}

const results = [];
for (const item of $input.all()) {
  const e = item.json;
  const subject = String(e.subject || '');
  const fromAddr = String(e.from?.value?.[0]?.address || e.from?.text || e.from || '').toLowerCase();

  if (!fromAddr.includes(OWNER_EMAIL)) continue;                 // only accept replies from you
  if (!/^\s*(re|aw|sv|antw)\s*:/i.test(subject)) continue;       // must be a reply
  const m = subject.match(/Ticket #(AS-[A-Z0-9]+)/i);
  if (!m) continue;

  const id = m[1].toUpperCase();
  const ticket = store.tickets[id];
  if (!ticket) continue;

  let text = e.text || e.textPlain || '';
  if (!text && (e.html || e.textHtml)) {
    text = String(e.html || e.textHtml)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n')
      .replace(/<[^>]+>/g, '');
  }

  let answer = stripQuoted(text);
  if (/^(approve|approved|ok|send|send it|yes)[.!]?$/i.test(answer)) answer = ticket.draft;
  if (!answer) continue;

  ticket.status = 'answered';
  ticket.answer = answer;
  ticket.answered_at = Date.now();

  results.push({
    json: {
      ticket_id: id,
      gmail_message_id: e.id,
      user_name: ticket.name,
      user_email: ticket.email,
      user_message: ticket.message,
      user_message_html: String(ticket.message).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/\n/g, '<br>'),
      answer
    }
  });
}
return results;

// Website polls this to show the human answer
const id = String($('Webhook: Ticket Status').first().json.query?.id || '').trim().toUpperCase();
const tickets = $getWorkflowStaticData('global').tickets || {};
const t = tickets[id];

if (!t) return [{ json: { ticket_id: id, status: 'not_found' } }];

return [{
  json: {
    ticket_id: id,
    status: t.status,
    answer: t.status === 'answered' ? t.answer : null,
    answered_at: t.answered_at ? new Date(t.answered_at).toISOString() : null
  }
}];
